INSERT INTO `talk_session` VALUES (1003,'individual','2026-05-09 00:00:00','222','张三','test1','admin','2026-05-28 21:27:41','',NULL),(1004,'individual','2026-05-13 00:00:00','002','张三','【谈话目的】了解学生学习困难，分析原因并制定帮扶计划。\n\n【谈话要点】\n1. 近期学习情况回顾，是否存在挂科、缺课现象\n2. 学习困难的主要原因分析\n3. 制定具体的学习改进计划\n4. 明确后续跟进时间和方式\n\n【谈话记录】','admin','2026-05-29 20:51:02','',NULL),(1005,'individual','2026-05-12 00:00:00','006','王五','【谈话目的】了解毕业生就业意向，提供就业指导和资源支持。\n\n【谈话要点】\n1. 就业意向和职业规划了解\n2. 简历和面试准备情况\n3. 当前就业市场形势分析\n4. 学校就业资源和服务介绍\n5. 制定求职行动计划\n\n【谈话记录】','admin','2026-05-30 18:32:08','',NULL),(1006,'group','2026-05-13 00:00:00','555','张三','【谈话目的】针对违纪行为进行教育，引导学生认识错误并改正。\n\n【谈话要点】\n1. 明确违纪事实，听取学生陈述\n2. 解读相关校规校纪\n3. 引导学生认识错误的性质和后果\n4. 共同制定改正计划\n5. 告知后续处理流程\n\n【谈话记录】','admin','2026-05-31 18:55:29','',NULL);
/*!40000 ALTER TABLE `talk_session` ENABLE KEYS */;
UNLOCK TABLES;

